def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(c for c in range(w) if len({row[c] for row in grid}) == 1)
    left = [row[:divider] for row in grid]
    right = [row[divider + 1:] for row in grid]
    background = max(set(x for row in right for x in row),
                     key=lambda x: sum(v == x for row in right for v in row))
    out = [[background] * len(right[0]) for _ in range(h)]
    for r in range(h):
        for c in range(min(len(left[r]), len(right[r]))):
            if left[r][c] != 0 and left[r][c] != 5:
                out[r][c] = 3
    return out
